-- ** Batch
-- | Batch
data Batch = Batch
  { batchId :: !(Text) -- ^ /Required/ "id"
  , batchObject :: !(E'Object2) -- ^ /Required/ "object" - The object type, which is always &#x60;batch&#x60;.
