  , batchCompletionWindow :: !(Text) -- ^ /Required/ "completion_window" - The time frame within which the batch should be processed.
  , batchStatus :: !(E'Status) -- ^ /Required/ "status" - The current status of the batch.
  , batchOutputFileId :: !(Maybe Text) -- ^ "output_file_id" - The ID of the file containing the outputs of successfully executed requests.
  , batchErrorFileId :: !(Maybe Text) -- ^ "error_file_id" - The ID of the file containing the outputs of requests with errors.
  , batchCreatedAt :: !(Int) -- ^ /Required/ "created_at" - The Unix timestamp (in seconds) for when the batch was created.
  , batchInProgressAt :: !(Maybe Int) -- ^ "in_progress_at" - The Unix timestamp (in seconds) for when the batch started processing.
  , batchExpiresAt :: !(Maybe Int) -- ^ "expires_at" - The Unix timestamp (in seconds) for when the batch will expire.
  , batchFinalizingAt :: !(Maybe Int) -- ^ "finalizing_at" - The Unix timestamp (in seconds) for when the batch started finalizing.
  , batchCompletedAt :: !(Maybe Int) -- ^ "completed_at" - The Unix timestamp (in seconds) for when the batch was completed.
  , batchFailedAt :: !(Maybe Int) -- ^ "failed_at" - The Unix timestamp (in seconds) for when the batch failed.
  , batchExpiredAt :: !(Maybe Int) -- ^ "expired_at" - The Unix timestamp (in seconds) for when the batch expired.
  , batchCancellingAt :: !(Maybe Int) -- ^ "cancelling_at" - The Unix timestamp (in seconds) for when the batch started cancelling.
  , batchCancelledAt :: !(Maybe Int) -- ^ "cancelled_at" - The Unix timestamp (in seconds) for when the batch was cancelled.
  , batchRequestCounts :: !(Maybe BatchRequestCounts) -- ^ "request_counts"
  , batchMetadata :: !(Maybe A.Value) -- ^ "metadata" - Set of 16 key-value pairs that can be attached to an object. This can be useful for storing additional information about the object in a structured format. Keys can be a maximum of 64 characters long and values can be a maximum of 512 characters long. 
  } deriving (P.Show, P.Eq, P.Typeable)

