      <$> (o .:  "id")
      <*> (o .:  "object")
      <*> (o .:  "endpoint")
      <*> (o .:? "errors")
      <*> (o .:  "input_file_id")
      <*> (o .:  "completion_window")
      <*> (o .:  "status")
      <*> (o .:? "output_file_id")
      <*> (o .:? "error_file_id")
      <*> (o .:  "created_at")
      <*> (o .:? "in_progress_at")
      <*> (o .:? "expires_at")
      <*> (o .:? "finalizing_at")
      <*> (o .:? "completed_at")
      <*> (o .:? "failed_at")
      <*> (o .:? "expired_at")
      <*> (o .:? "cancelling_at")
      <*> (o .:? "cancelled_at")
      <*> (o .:? "request_counts")
      <*> (o .:? "metadata")

