instance A.ToJSON Batch where
  toJSON Batch {..} =
   _omitNulls
      [ "id" .= batchId
      , "object" .= batchObject
      , "endpoint" .= batchEndpoint
      , "errors" .= batchErrors
      , "input_file_id" .= batchInputFileId
      , "completion_window" .= batchCompletionWindow
      , "status" .= batchStatus
      , "output_file_id" .= batchOutputFileId
      , "error_file_id" .= batchErrorFileId
      , "created_at" .= batchCreatedAt
      , "in_progress_at" .= batchInProgressAt
      , "expires_at" .= batchExpiresAt
      , "finalizing_at" .= batchFinalizingAt
      , "completed_at" .= batchCompletedAt
      , "failed_at" .= batchFailedAt
