      <$> (o .:  "id")
      <*> (o .:  "created_at")
      <*> (o .:  "error")
      <*> (o .:  "fine_tuned_model")
      <*> (o .:  "finished_at")
      <*> (o .:  "hyperparameters")
      <*> (o .:  "model")
      <*> (o .:  "object")
      <*> (o .:  "organization_id")
      <*> (o .:  "result_files")
      <*> (o .:  "status")
      <*> (o .:  "trained_tokens")
      <*> (o .:  "training_file")
      <*> (o .:  "validation_file")
      <*> (o .:? "integrations")
      <*> (o .:  "seed")
      <*> (o .:? "estimated_finish")
      <*> (o .:? "method")

