-- ** AudioResponseFormat

-- | Enum of 'Text' .
-- The format of the output, in one of these options: `json`, `text`, `srt`, `verbose_json`, or `vtt`. 
data AudioResponseFormat
  = AudioResponseFormat'Json -- ^ @"json"@
  | AudioResponseFormat'Text -- ^ @"text"@
  | AudioResponseFormat'Srt -- ^ @"srt"@
  | AudioResponseFormat'Verbose_json -- ^ @"verbose_json"@
  | AudioResponseFormat'Vtt -- ^ @"vtt"@
  deriving (P.Show, P.Eq, P.Typeable, P.Ord, P.Bounded, P.Enum)

instance A.ToJSON AudioResponseFormat where toJSON = A.toJSON . fromAudioResponseFormat
instance A.FromJSON AudioResponseFormat where parseJSON o = P.either P.fail (pure . P.id) . toAudioResponseFormat =<< A.parseJSON o
instance WH.ToHttpApiData AudioResponseFormat where toQueryParam = WH.toQueryParam . fromAudioResponseFormat
instance WH.FromHttpApiData AudioResponseFormat where parseQueryParam o = WH.parseQueryParam o >>= P.left T.pack . toAudioResponseFormat
instance MimeRender MimeMultipartFormData AudioResponseFormat where mimeRender _ = mimeRenderDefaultMultipartFormData

-- | unwrap 'AudioResponseFormat' enum
fromAudioResponseFormat :: AudioResponseFormat -> Text
fromAudioResponseFormat = \case
  AudioResponseFormat'Json -> "json"
  AudioResponseFormat'Text -> "text"
  AudioResponseFormat'Srt -> "srt"
  AudioResponseFormat'Verbose_json -> "verbose_json"
  AudioResponseFormat'Vtt -> "vtt"

-- | parse 'AudioResponseFormat' enum
toAudioResponseFormat :: Text -> P.Either String AudioResponseFormat
toAudioResponseFormat = \case
  "json" -> P.Right AudioResponseFormat'Json
  "text" -> P.Right AudioResponseFormat'Text
  "srt" -> P.Right AudioResponseFormat'Srt
  "verbose_json" -> P.Right AudioResponseFormat'Verbose_json
  "vtt" -> P.Right AudioResponseFormat'Vtt
  s -> P.Left $ "toAudioResponseFormat: enum parse failure: " P.++ P.show s


