  s -> P.Left $ "toE'Voice2: enum parse failure: " P.++ P.show s


-- ** E'Weight

-- | Enum of 'Int' .
-- Controls whether the assistant message is trained against (0 or 1)
data E'Weight
  = E'Weight'Num0 -- ^ @0@
  | E'Weight'Num1 -- ^ @1@
  deriving (P.Show, P.Eq, P.Typeable, P.Ord, P.Bounded, P.Enum)

instance A.ToJSON E'Weight where toJSON = A.toJSON . fromE'Weight
instance A.FromJSON E'Weight where parseJSON o = P.either P.fail (pure . P.id) . toE'Weight =<< A.parseJSON o
instance WH.ToHttpApiData E'Weight where toQueryParam = WH.toQueryParam . fromE'Weight
instance WH.FromHttpApiData E'Weight where parseQueryParam o = WH.parseQueryParam o >>= P.left T.pack . toE'Weight
instance MimeRender MimeMultipartFormData E'Weight where mimeRender _ = mimeRenderDefaultMultipartFormData

-- | unwrap 'E'Weight' enum
fromE'Weight :: E'Weight -> Int
fromE'Weight = \case
  E'Weight'Num0 -> 0
  E'Weight'Num1 -> 1

-- | parse 'E'Weight' enum
toE'Weight :: Int -> P.Either String E'Weight
toE'Weight = \case
  0 -> P.Right E'Weight'Num0
  1 -> P.Right E'Weight'Num1
  s -> P.Left $ "toE'Weight: enum parse failure: " P.++ P.show s


